def welford(xs):
    n = 0; mean = 0.0; m2 = 0.0
    for x in xs:
        n += 1
        d = x - mean
        mean += d / n
        m2 += d * (x - mean)
    return mean, m2 / n, m2 / (n - 1)

print(*welford([2, 4, 4, 4, 5, 5, 7, 9]))
